import hashlib
import hmac
import os
import sqlite3
import unicodedata
from flask import Flask, request, jsonify, g, session
from functools import wraps
import secrets
import re

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

DATABASE = ':memory:'
ADMIN_USERS = set()

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        init_db(g.db)
    return g.db

def init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        display_name TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY,
        key_hash TEXT NOT NULL,
        username TEXT NOT NULL,
        scope TEXT NOT NULL DEFAULT 'read'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        actor TEXT NOT NULL,
        action TEXT NOT NULL,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

# --- Username normalization and validation ---

BLOCKED_NAMES = {'admin', 'administrator', 'root', 'system', 'superuser'}

def canonicalize_username(raw):
    """Normalize username to canonical form for storage and lookup."""
    # Strip leading/trailing whitespace
    stripped = raw.strip()
    # NFKC normalization for Unicode equivalence
    normalized = unicodedata.normalize('NFKC', stripped)
    # Case fold for case-insensitive comparison
    folded = normalized.casefold()
    return folded

def is_valid_username(username):
    """Check if username meets format requirements."""
    if len(username) < 3 or len(username) > 30:
        return False
    # Allow alphanumeric, underscore, hyphen, and some Unicode letters
    if not re.match(r'^[\w\-]+$', username, re.UNICODE):
        return False
    return True

def is_blocked_name(username):
    """Check if the username is in the blocked list."""
    return username in BLOCKED_NAMES

# --- Authentication ---

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if api_key:
            db = get_db()
            key_hash = hashlib.sha256(api_key.encode('utf-8')).hexdigest()
            row = db.execute('SELECT username, scope FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
            if row:
                g.current_user = row['username']
                g.current_scope = row['scope']
                return f(*args, **kwargs)
        return jsonify({'error': 'Authentication required'}), 401
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not hasattr(g, 'current_user'):
            return jsonify({'error': 'Authentication required'}), 401
        db = get_db()
        user = db.execute('SELECT role FROM users WHERE username = ?', (g.current_user,)).fetchone()
        if not user or user['role'] != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return decorated

# --- Registration flow ---

@app.route('/api/register', methods=['POST'])
def register_user():
    data = request.get_json()
    if not data or 'username' not in data or 'display_name' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    raw_username = data['username']
    display_name = data.get('display_name', raw_username)

    # Step 1: Validate format of raw input
    if not is_valid_username(raw_username):
        return jsonify({'error': 'Invalid username format'}), 400

    # Step 2: Check blocked names against raw input
    if is_blocked_name(raw_username.casefold()):
        return jsonify({'error': 'Username is reserved'}), 400

    # Step 3: Canonicalize for storage
    canonical = canonicalize_username(raw_username)

    # Step 4: Store the canonical form
    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, display_name, role) VALUES (?, ?, ?)',
            (canonical, display_name, 'user')
        )
        # Generate API key
        api_key = secrets.token_urlsafe(32)
        key_hash = hashlib.sha256(api_key.encode('utf-8')).hexdigest()
        db.execute(
            'INSERT INTO api_keys (key_hash, username, scope) VALUES (?, ?, ?)',
            (key_hash, canonical, 'read')
        )
        db.commit()

        db.execute(
            'INSERT INTO audit_log (actor, action, target) VALUES (?, ?, ?)',
            ('system', 'user_registered', canonical)
        )
        db.commit()

        return jsonify({
            'username': canonical,
            'api_key': api_key,
            'message': 'Registration successful'
        }), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409

# --- Role management ---

@app.route('/api/admin/promote', methods=['POST'])
@require_auth
@require_admin
def promote_user():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Missing username'}), 400

    target = canonicalize_username(data['username'])
    db = get_db()

    result = db.execute('UPDATE users SET role = ? WHERE username = ?', ('admin', target))
    db.commit()

    if result.rowcount == 0:
        return jsonify({'error': 'User not found'}), 404

    db.execute(
        'INSERT INTO audit_log (actor, action, target) VALUES (?, ?, ?)',
        (g.current_user, 'promote_to_admin', target)
    )
    db.commit()

    return jsonify({'message': f'User {target} promoted to admin'}), 200

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    db = get_db()
    users = db.execute('SELECT username, display_name, role FROM users').fetchall()
    return jsonify([dict(u) for u in users]), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    db = get_db()
    user = db.execute('SELECT username, display_name, role FROM users WHERE username = ?', (g.current_user,)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user)), 200

# --- Seed initial admin ---

def seed_admin():
    """Create initial admin user for bootstrapping."""
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        display_name TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY,
        key_hash TEXT NOT NULL,
        username TEXT NOT NULL,
        scope TEXT NOT NULL DEFAULT 'read'
    )''')
    try:
        db.execute(
            'INSERT INTO users (username, display_name, role) VALUES (?, ?, ?)',
            ('admin', 'System Administrator', 'admin')
        )
        admin_key = os.environ.get('ADMIN_API_KEY', 'admin-bootstrap-key-change-me')
        key_hash = hashlib.sha256(admin_key.encode('utf-8')).hexdigest()
        db.execute(
            'INSERT INTO api_keys (key_hash, username, scope) VALUES (?, ?, ?)',
            (key_hash, 'admin', 'write')
        )
        db.commit()
    except sqlite3.IntegrityError:
        pass
    db.close()

